QUERIES = [
{'level':'Beginner','title':'India players','purpose':'List Indian players and their roles/styles.','sql':"SELECT p.full_name,p.role,p.batting_style,p.bowling_style FROM players p JOIN teams t ON p.team_id=t.team_id WHERE t.team_name='India' ORDER BY p.full_name;"},
{'level':'Beginner','title':'Matches in last 30 days','purpose':'Recent matches with teams and venue.','sql':"SELECT m.description,t1.team_name team1,t2.team_name team2,v.venue_name,v.city,m.match_date FROM matches m JOIN teams t1 ON m.team1_id=t1.team_id JOIN teams t2 ON m.team2_id=t2.team_id LEFT JOIN venues v ON m.venue_id=v.venue_id WHERE date(m.match_date)>=date('now','-30 days') ORDER BY m.match_date DESC;"},
{'level':'Beginner','title':'Top run scorers','purpose':'Rank players by stored career run totals.','sql':"SELECT full_name,runs AS total_runs,batting_average,matches FROM players ORDER BY runs DESC LIMIT 10;"},
{'level':'Beginner','title':'Large venues','purpose':'Venues with capacity above 50,000.','sql':"SELECT venue_name,city,country,capacity FROM venues WHERE capacity>50000 ORDER BY capacity DESC;"},
{'level':'Beginner','title':'Wins by team','purpose':'Count matches won by each team.','sql':"SELECT t.team_name,COUNT(m.match_id) wins FROM teams t LEFT JOIN matches m ON m.winner_team_id=t.team_id GROUP BY t.team_id ORDER BY wins DESC;"},
{'level':'Beginner','title':'Players by role','purpose':'Count players in each role.','sql':"SELECT role,COUNT(*) player_count FROM players GROUP BY role ORDER BY player_count DESC;"},
{'level':'Beginner','title':'Highest individual score by format','purpose':'Highest recorded innings score per format.','sql':"SELECT m.format,MAX(s.runs) highest_score FROM batting_scores s JOIN innings i ON s.innings_id=i.innings_id JOIN matches m ON i.match_id=m.match_id GROUP BY m.format;"},
{'level':'Beginner','title':'Series starting in 2024','purpose':'Series are not modeled; this query checks match dates instead.','sql':"SELECT description,format,match_date FROM matches WHERE strftime('%Y',match_date)='2024' ORDER BY match_date;"},
{'level':'Intermediate','title':'All-rounders with 1000 runs and 50 wickets','purpose':'Identify high-contribution all-rounders.','sql':"SELECT full_name,runs,wickets FROM players WHERE role='All-rounder' AND runs>1000 AND wickets>50 ORDER BY runs DESC;"},
{'level':'Intermediate','title':'Last 20 completed matches','purpose':'Recent results with winner and venue.','sql':"SELECT m.description,t1.team_name team1,t2.team_name team2,w.team_name winner,m.win_margin,m.win_type,v.venue_name,m.match_date FROM matches m JOIN teams t1 ON m.team1_id=t1.team_id JOIN teams t2 ON m.team2_id=t2.team_id LEFT JOIN teams w ON m.winner_team_id=w.team_id LEFT JOIN venues v ON m.venue_id=v.venue_id WHERE m.status='Completed' ORDER BY m.match_date DESC LIMIT 20;"},
{'level':'Intermediate','title':'Runs by format','purpose':'Aggregate observed innings runs by player and format.','sql':"SELECT p.full_name,m.format,SUM(s.runs) innings_runs FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id GROUP BY p.player_id,m.format ORDER BY p.full_name,m.format;"},
{'level':'Intermediate','title':'Home versus away wins','purpose':'Compare winning team country to venue country.','sql':"SELECT t.team_name,CASE WHEN v.country=t.country THEN 'Home' ELSE 'Away' END condition_type,COUNT(*) wins FROM matches m JOIN teams t ON t.team_id=m.winner_team_id JOIN venues v ON v.venue_id=m.venue_id GROUP BY t.team_id,condition_type ORDER BY t.team_name;"},
{'level':'Intermediate','title':'Consecutive batter partnerships','purpose':'Find adjacent batting positions with combined 100+ runs.','sql':"SELECT s1.player_id batter_1,s2.player_id batter_2,s1.runs+s2.runs combined_runs,i.innings_id FROM batting_scores s1 JOIN batting_scores s2 ON s1.innings_id=s2.innings_id AND s2.batting_position=s1.batting_position+1 JOIN innings i ON i.innings_id=s1.innings_id WHERE s1.runs+s2.runs>=100;"},
{'level':'Intermediate','title':'Bowling by venue','purpose':'Calculate economy and wickets at each venue.','sql':"SELECT p.full_name,v.venue_name,COUNT(DISTINCT i.match_id) matches_played,SUM(b.wickets) wickets,SUM(b.runs_conceded)*1.0/NULLIF(SUM(b.overs),0) economy FROM bowling_figures b JOIN players p ON p.player_id=b.player_id JOIN innings i ON i.innings_id=b.innings_id JOIN matches m ON m.match_id=i.match_id JOIN venues v ON v.venue_id=m.venue_id GROUP BY p.player_id,v.venue_id ORDER BY economy;"},
{'level':'Intermediate','title':'Player performance in close matches','purpose':'Summarize runs in matches with close margins.','sql':"SELECT p.full_name,AVG(s.runs) average_runs,COUNT(DISTINCT m.match_id) close_matches FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id WHERE (m.win_type='runs' AND m.win_margin<50) OR (m.win_type='wickets' AND m.win_margin<5) GROUP BY p.player_id ORDER BY average_runs DESC;"},
{'level':'Intermediate','title':'Yearly batting trends','purpose':'Average runs and strike rate per year.','sql':"SELECT p.full_name,strftime('%Y',m.match_date) year,AVG(s.runs) average_runs,AVG(100.0*s.runs/NULLIF(s.balls,0)) average_strike_rate,COUNT(DISTINCT m.match_id) matches FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id WHERE m.match_date>='2020-01-01' GROUP BY p.player_id,year HAVING matches>=1 ORDER BY year DESC,average_runs DESC;"},
{'level':'Advanced','title':'Toss advantage','purpose':'Toss fields are not available in the demo schema.','sql':"SELECT 'Requires toss_winner_team_id and toss_decision fields' AS note;"},
{'level':'Advanced','title':'Economical limited-overs bowlers','purpose':'Rank ODI/T20I bowlers using available figures.','sql':"SELECT p.full_name,SUM(b.wickets) wickets,SUM(b.runs_conceded)*1.0/NULLIF(SUM(b.overs),0) economy,COUNT(DISTINCT i.match_id) matches FROM bowling_figures b JOIN players p ON p.player_id=b.player_id JOIN innings i ON i.innings_id=b.innings_id JOIN matches m ON m.match_id=i.match_id WHERE m.format IN ('ODI','T20I') GROUP BY p.player_id HAVING matches>=1 ORDER BY economy;"},
{'level':'Advanced','title':'Consistent batsmen','purpose':'Use innings range as a simple consistency proxy; standard deviation is not built into SQLite.','sql':"SELECT p.full_name,AVG(s.runs) average_runs,MIN(s.runs) min_runs,MAX(s.runs) max_runs,COUNT(*) innings FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id WHERE m.match_date>='2022-01-01' AND s.balls>=10 GROUP BY p.player_id ORDER BY (MAX(s.runs)-MIN(s.runs));"},
{'level':'Advanced','title':'Player matches and averages by format','purpose':'Count appearances and average observed innings runs.','sql':"SELECT p.full_name,m.format,COUNT(DISTINCT m.match_id) matches,AVG(s.runs) average_innings_runs FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id GROUP BY p.player_id,m.format ORDER BY p.full_name,m.format;"},
{'level':'Advanced','title':'Weighted player ranking','purpose':'Illustrative ranking from available batting/bowling totals; fielding metrics are absent.','sql':"SELECT full_name,((runs*0.01)+(batting_average*0.5)+(strike_rate*0.3)+(wickets*2)) weighted_score FROM players ORDER BY weighted_score DESC;"},
{'level':'Advanced','title':'Head-to-head comparison','purpose':'Compare wins between opponents in recorded fixtures.','sql':"SELECT a.team_name team_a,b.team_name team_b,COUNT(*) matches_played,SUM(CASE WHEN m.winner_team_id=a.team_id THEN 1 ELSE 0 END) team_a_wins,SUM(CASE WHEN m.winner_team_id=b.team_id THEN 1 ELSE 0 END) team_b_wins FROM matches m JOIN teams a ON a.team_id=m.team1_id JOIN teams b ON b.team_id=m.team2_id GROUP BY a.team_id,b.team_id ORDER BY matches_played DESC;"},
{'level':'Advanced','title':'Recent player form','purpose':'Compare last five and ten batting innings using a window function.','sql':"WITH ranked AS (SELECT p.full_name,s.runs,m.match_date,ROW_NUMBER() OVER(PARTITION BY p.player_id ORDER BY m.match_date DESC) rn FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id) SELECT full_name,AVG(CASE WHEN rn<=5 THEN runs END) avg_last_5,AVG(CASE WHEN rn<=10 THEN runs END) avg_last_10,SUM(CASE WHEN runs>=50 AND rn<=10 THEN 1 ELSE 0 END) fifties_last_10 FROM ranked WHERE rn<=10 GROUP BY full_name;"},
{'level':'Advanced','title':'Best partnerships','purpose':'Summarize adjacent batting-position pairs.','sql':"SELECT s1.player_id batter_1,s2.player_id batter_2,AVG(s1.runs+s2.runs) avg_partnership,MAX(s1.runs+s2.runs) highest_partnership,COUNT(*) partnerships FROM batting_scores s1 JOIN batting_scores s2 ON s1.innings_id=s2.innings_id AND s2.batting_position=s1.batting_position+1 GROUP BY s1.player_id,s2.player_id ORDER BY avg_partnership DESC;"},
{'level':'Advanced','title':'Quarterly performance trajectory','purpose':'Track quarterly runs and strike rates; history is limited in demo data.','sql':"SELECT p.full_name,strftime('%Y',m.match_date) year,CAST((CAST(strftime('%m',m.match_date) AS INTEGER)-1)/3+1 AS INTEGER) quarter,AVG(s.runs) avg_runs,AVG(100.0*s.runs/NULLIF(s.balls,0)) avg_strike_rate,COUNT(DISTINCT m.match_id) matches FROM players p JOIN batting_scores s ON s.player_id=p.player_id JOIN innings i ON i.innings_id=s.innings_id JOIN matches m ON m.match_id=i.match_id GROUP BY p.player_id,year,quarter ORDER BY p.full_name,year,quarter;"}
]
